  "sql": "WITH _base AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  GROUP BY\n    customers__regions.name\n), _cm_orders__order_items__id_count AS (\n  SELECT\n    orders__customers__regions.name AS \"order_items.orders.customers.regions.name\",\n    COUNT(order_items.id) AS \"order_items.id_count\"\n  FROM order_items AS order_items\n  LEFT JOIN orders AS orders\n    ON order_items.order_id = orders.id\n  LEFT JOIN customers AS orders__customers\n    ON orders.customer_id = orders__customers.id\n  LEFT JOIN regions AS orders__customers__regions\n    ON orders__customers.region_id = orders__customers__regions.id\n  GROUP BY\n    orders__customers__regions.name\n)\nSELECT\n  _base.\"orders.customers.regions.name\",\n  _base.\"orders.revenue\",\n  COALESCE(_cm_orders__order_items__id_count.\"order_items.id_count\", 0) AS \"orders.order_lines\"\nFROM _base\nLEFT JOIN _cm_orders__order_items__id_count\n  ON _base.\"orders.customers.regions.name\" IS NOT DISTINCT FROM _cm_orders__order_items__id_count.\"order_items.orders.customers.regions.name\"\nORDER BY\n  _base.\"orders.customers.regions.name\" ASC\nLIMIT 101"
}

